def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]
    opp_d_total = sum(1 for a, b in history if b == 'D')
    my_d_total = sum(1 for a, b in history if a == 'D')

    recent5 = history[-5:] if n >= 5 else history
    opp_d5 = sum(1 for a, b in recent5 if b == 'D')
    recent10 = history[-10:] if n >= 10 else history
    opp_d10 = sum(1 for a, b in recent10 if b == 'D')

    if n < 5:
        return 'C'

    if opp_d10 >= 4:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_d5 >= 2:
                return 'D'
            return 'C'
        else:
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
    else:
        if my_last == 'D':
            return 'C'
        else:
            if opp_d5 > 0:
                return 'C'
            if opp_d_total == 0:
                if n >= 10 and n % 4 == 0:
                    return 'D'
                return 'C'
            else:
                forgives = sum(1 for a, b in history if a == 'D' and b == 'C')
                if forgives >= 2 and n >= 20 and n % 10 == 0:
                    return 'D'
                return 'C'
